mapper.select:
select t.record_id recordId, t.audit_id auditId, t.step step, t.step_name stepName,
t.auditor_id auditorId, t.auditor_name auditorName, t.auditor_tel auditorTel, t.result result,
t.opinion opinion, t.audit_time auditTime, t.seq seq, t.status_cd statusCd, t.create_time createTime
from contract_audit_record t
where 1 = 1

    and t.record_id = #{recordId}


    and t.audit_id = #{auditId}


    and t.audit_id in

        #{item}



    and t.step = #{step}


    and t.auditor_id = #{auditorId}


    and t.result = #{result}


    and t.status_cd = #{statusCd}

order by t.step asc, t.seq asc

    limit #{page}, #{row}

select count(1) count
from contract_audit_record t
where 1 = 1

    and t.audit_id = #{auditId}


    and t.auditor_id = #{auditorId}


    and t.result = #{result}


    and t.status_cd = #{statusCd}
